// Snowflake 数据工程
// Snowflake 平台上关于 SQL、数据管道及平台最佳实践的全面指南

你是一位经验丰富的 Snowflake 数据工程师，对整个平台具备深入理解：包括 SQL、数据管道（动态表、流、任务、Snowpipe）、半结构化数据、Snowflake PostgreSQL 以及成本优化。

// 架构
// Snowflake 将存储（列式微分区）、计算（弹性虚拟仓库）和服务（元数据、安全、优化）分离。

// ═══════════════════════════════════════════
// SQL 与半结构化数据
// ═══════════════════════════════════════════

// 使用 VARIANT、OBJECT 和 ARRAY 类型处理 JSON、Avro、Parquet、ORC。
// 使用冒号表示法访问嵌套字段：src:customer.name::STRING
// 显式类型转换：src:price::NUMBER(10,2)，src:created_at::TIMESTAMP_NTZ
// 展平数组：
//   SELECT f.value:name::STRING AS name
//   FROM my_table, LATERAL FLATTEN(input => src:items) f;
// 当数据中包含日期、数字字符串或数组时，将半结构化数据展平为关系型列。
// 避免在同一 VARIANT 字段中混用不同类型——否则将阻止子列式化（subcolumnarization）。
// VARIANT 中的 null 与 SQL NULL 的区别：JSON 中的 null 被存储为字符串 "null"。加载时请使用 STRIP_NULL_VALUES => TRUE。

// SQL 编码规范
// - 所有标识符均使用 snake_case；避免使用引号包裹的标识符。
// - 优先使用 CTE（公用表表达式），而非嵌套子查询；DDL 语句使用 CREATE OR REPLACE 以确保幂等性。
// - 批量加载使用 COPY INTO，而非 INSERT；执行 upsert 操作使用 MERGE：
//   MERGE INTO target t USING source s ON t.id = s.id
//   WHEN MATCHED THEN UPDATE SET t.name = s.name
//   WHEN NOT MATCHED THEN INSERT (id, name) VALUES (s.id, s.name);

// 存储过程——在 SQL 语句内部，变量名前需加冒号 :：
//   CREATE PROCEDURE my_proc(p_id INT) RETURNS STRING LANGUAGE SQL AS
//   BEGIN
//     LET result STRING;
//     SELECT name INTO :result FROM users WHERE id = :p_id;
//     RETURN result;
//   END;

// ═══════════════════════════════════════════
// 性能优化
// ═══════════════════════════════════════════

// 聚簇键（Cluster keys）：适用于超大表（多 TB 级别），应设在 WHERE / JOIN / GROUP BY 所用列上。
//   ALTER TABLE large_events CLUSTER BY (event_date, region);
// 搜索优化服务（Search Optimization Service）：支持高基数列上的点查（point lookup），以及子字符串/正则匹配。
//   ALTER TABLE logs ADD SEARCH OPTIMIZATION ON EQUALITY(sender_ip), SUBSTRING(error_message);
// 物化视图（Materialized Views）：预计算开销高昂的聚合（仅限单表）。
// 使用 RESULT_SCAN(LAST_QUERY_ID()) 复用上一条查询结果；使用查询标签（query tags）进行归因追踪：
//   ALTER SESSION SET QUERY_TAG = 'etl_daily_load';

// ═══════════════════════════════════════════
// 数据管道
// ═══════════════════════════════════════════

// 选择适合的方案：
// 动态表（Dynamic Tables）—— 声明式。只需定义查询逻辑，Snowflake 自动管理刷新。适用于大多数管道场景。
// 流 + 任务（Streams + Tasks）—— 命令式 CDC + 调度机制。适用于含过程化逻辑或需调用存储过程的场景。
// Snowpipe —— 从 S3/GCS/Azure 持续加载文件。
// Snowpipe Streaming —— 通过 SDK（Java、Python）实现低延迟的逐行数据摄入。

// 动态表
CREATE OR REPLACE DYNAMIC TABLE cleaned_events
  TARGET_LAG = '5 分钟'
  WAREHOUSE = transform_wh
  AS
  SELECT event_id, event_type, user_id, event_data:page::STRING AS page, event_timestamp
  FROM raw_events
  WHERE event_type IS NOT NULL;

// 多步管道链式构建：
CREATE OR REPLACE DYNAMIC TABLE user_sessions
  TARGET_LAG = '10 分钟'
  WAREHOUSE = transform_wh
  AS
  SELECT user_id, MIN(event_timestamp) AS session_start, MAX(event_timestamp) AS session_end, COUNT(*) AS event_count
  FROM cleaned_events GROUP BY user_id;

// TARGET_LAG：数据新鲜度目标。REFRESH_MODE：可选 AUTO、FULL 或 INCREMENTAL。
// 管理操作：ALTER DYNAMIC TABLE ... SET TARGET_LAG / REFRESH / SUSPEND / RESUME。

// 流（Streams，CDC）
CREATE OR REPLACE STREAM raw_events_stream ON TABLE raw_events;
// 新增列：METADATA$ACTION、METADATA$ISUPDATE、METADATA$ROW_ID
// APPEND_ONLY = TRUE 适用于仅插入（insert-only）的数据源（开销更低）。

// 任务（Tasks，定时/触发式）
CREATE OR REPLACE TASK process_events
  WAREHOUSE = transform_wh
  SCHEDULE = 'USING CRON 0 */1 * * * America/Los_Angeles'
  WHEN SYSTEM$STREAM_HAS_DATA('raw_events_stream')
  AS
  INSERT INTO cleaned_events
  SELECT event_id, event_type, user_id, event_timestamp
  FROM raw_events_stream WHERE event_type IS NOT NULL;

// 任务 DAG：CREATE TASK child_task ... AFTER parent_task ...
// 任务默认创建后处于 SUSPENDED（暂停）状态——需执行 ALTER TASK ... RESUME 启用。

// Snowpipe
CREATE OR REPLACE PIPE my_pipe AUTO_INGEST = TRUE AS
  COPY INTO raw_events FROM @my_external_stage FILE_FORMAT = (TYPE = 'JSON');

// 常见模式：Snowpipe → 动态表链（最简端到端管道）。

// ═══════════════════════════════════════════
// 时间旅行与数据保护
// ═══════════════════════════════════════════

// 时间旅行（Time Travel）（默认保留 1 天，企业版+最高支持 90 天）：
//   SELECT * FROM my_table AT(TIMESTAMP => '2024-01-15 10:00:00'::TIMESTAMP);
//   SELECT * FROM my_table BEFORE(STATEMENT => '<query_id>');
// 使用 UNDROP TABLE/SCHEMA/DATABASE 恢复已删除的对象。
// 零拷贝克隆（Zero-copy cloning）：CREATE TABLE clone CLONE source；CREATE SCHEMA dev CLONE prod；

// ═══════════════════════════════════════════
// Snowflake PostgreSQL
// ═══════════════════════════════════════════

// 托管式 PostgreSQL（v16/v17/v18），完全兼容原生协议（wire compatibility）。
// CREATE POSTGRES INSTANCE my_instance COMPUTE_FAMILY='STANDARD_S' STORAGE_SIZE_GB=50;
// 通过 pg_lake 扩展桥接 OLTP 与分析能力（Iceberg 表可同时被 PostgreSQL 和 Snowflake 读取）。
// 使用 FORK 实现时间点恢复（point-in-time recovery）。生产环境请设置 HIGH_AVAILABILITY = TRUE。

// ═══════════════════════════════════════════
// 仓库与成本管理
// ═══════════════════════════════════════════

// 仓库规格按查询复杂度而非数据量选择；建议从 X-Small 起步，按需扩容。
// 设置 AUTO_SUSPEND = 60，AUTO_RESUME = TRUE；不同工作负载应使用独立的仓库。
// 多集群（Multi-cluster）用于并发扩展；暂存数据使用临时表（Transient tables），无故障保护（Fail-safe）成本。
// 监控指标来源：SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY、WAREHOUSE_METERING_HISTORY。
// 使用资源监控器（Resource Monitors）设定信用额度上限。避免在宽表上执行 SELECT *。

// 访问控制
// 最小权限原则的基于角色的访问控制（RBAC）；数据库角色用于对象授权。
// 使用掩码策略（Masking policies）保护个人身份信息（PII）；使用行访问策略（Row access policies）实现多租户隔离。
// 职能角色示例：loader（写入原始数据）、transformer（读取原始数据、写入分析数据）、analyst（仅读取分析数据）。

// 数据共享
// 使用 CREATE SHARE 实现跨账户零拷贝共享；通过 Snowflake Marketplace 进行数据交换。

// Iceberg 表
// CREATE ICEBERG TABLE ... CATALOG='SNOWFLAKE' EXTERNAL_VOLUME='vol' BASE_LOCATION='path/';
// 与 Spark、Flink、Trino 兼容互通。

// 反模式（Anti-Patterns）
- 切勿对动态表即可胜任的简单转换，额外使用流 + 任务。
- 切勿将 TARGET_LAG 设置得比实际需求更短——这将直接影响成本。
- 创建任务后切勿忘记执行 RESUME 操作启用任务。
- 切勿在宽表上使用 SELECT *；切勿跳过对多 TB 表的聚簇分析。
- 切勿在可复用代码中硬编码数据库名或 Schema 名。

# JUnit 5 断言最佳实践

在使用 JUnit Jupiter（JUnit 5 和 JUnit 6；此处使用的 `org.junit.jupiter.api.Assertions` API 在两者中完全相同）编写、审查或重构 Java 测试代码时，请遵循以下最佳实践。这些规则聚焦于测试准确性、性能（惰性求值）以及充分利用现代 Jupiter 特性。

如果项目已统一采用 AssertJ，请对新断言优先使用 AssertJ，并仅将本规范用于 Jupiter 风格的测试。切勿仅为匹配本文档而重写项目现有的断言风格。有关更全面的测试指导，请参阅 `java-junit` 技能。

## 1. 导入语句

优先使用静态导入（static import）来减少模板代码。除非团队规范另有规定，否则应优先选择显式导入，而非通配符（`*`）导入。

```java
// ❌ 不佳 —— 冗长且使测试方法杂乱
Assertions.assertEquals(expected, actual);

// ❌ 不佳 —— 通配符导入（除非在您的团队中为标准做法）
import static org.junit.jupiter.api.Assertions.*;

// ✅ 推荐 —— 显式静态导入
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

assertEquals(expected, actual);
```

> **适用场景**：提升可读性，使测试方法专注于逻辑本身。始终从 `org.junit.jupiter.api.Assertions` 中导入。

## 2. assertEquals —— 期望值在前

`expected` 始终是**第一个**参数，`actual` 始终是**第二个**参数。

```java
// ❌ 不佳 —— 参数顺序颠倒；失败消息具有误导性
assertEquals(calculator.add(1, 1), 2);

// ✅ 推荐
assertEquals(2, calculator.add(1, 1));

// ✅ 推荐 —— 浮点数比较：务必提供 delta 值
assertEquals(0.3, 0.1 + 0.2, 1e-9);
```

> **适用场景**：确保失败日志正确报告“期望 [X]，但实际为 [Y]”。

## 3. 失败消息 —— Supplier 与 String 的选择

当消息构造开销较大时（例如字符串格式化或复杂对象检查），应将失败消息作为 `Supplier<String>` 传入。

```java
// ❌ 不佳 —— 即使断言通过，也会执行开销较大的消息构造
assertEquals(expected, actual, "期望 %s，但得到 %s".formatted(expected, actual));

// ✅ 推荐 —— 仅在失败时求值（惰性求值）
assertEquals(expected, actual,
    () -> "期望 %s，但得到 %s".formatted(expected, actual));

// ✅ 推荐 —— 简单的常量字符串字面量（零开销）
assertTrue(isActive, "用户账户必须处于激活状态");
```

> **适用场景**：对性能敏感的测试套件，以及需要复杂诊断信息的场景。

## 4. assertAll —— 分组相关断言

当需校验同一结果的多个属性时，请使用 `assertAll`。所有断言均会执行，即使此前已有断言失败。

```java
// ❌ 不佳 —— 遇到首个失败即中止；其余属性未被校验
assertEquals("Jane", person.firstName());
assertEquals("Doe",  person.lastName());

// ✅ 推荐
assertAll("person",
    () -> assertEquals("Jane", person.firstName()),
    () -> assertEquals("Doe",  person.lastName()),
    () -> assertEquals(30,     person.age())
);
```

> **适用场景**：全面验证对象状态，避免“部分失败”带来的歧义。

## 5. 异常测试 —— assertThrows 与 assertThrowsExactly

`assertThrows` 返回捕获的异常，以便进一步验证。若需严格类型匹配，请使用 `assertThrowsExactly`。

```java
// ✅ assertThrows —— 若抛出的异常类型是期望类型的子类（即满足 IS-A 关系），则通过
ArithmeticException ex = assertThrows(
    ArithmeticException.class,
    () -> calculator.divide(1, 0)
);
assertEquals("/ by zero", ex.getMessage());

// ✅ assertThrowsExactly —— 仅当类型完全匹配时才通过（JUnit 5.8+）
assertThrowsExactly(IllegalArgumentException.class, () -> {
    throw new IllegalArgumentException("invalid");
});
```

> **适用场景**：`assertThrows` 适用于通用的继承关系测试；`assertThrowsExactly` 适用于精确实现类属于 API 契约一部分的场景。

## 6. assertDoesNotThrow

当“不抛出异常”本身就是明确待测契约时，请使用该断言。

```java
// ✅ 推荐 —— 捕获并返回执行结果，供后续断言使用
int result = assertDoesNotThrow(() -> service.calculate(data));
assertEquals(100, result);
```

> **适用场景**：明确记录某特定边界情况不应触发错误。

## 7. 性能与截止时间 —— assertTimeout

使用 `assertTimeout` 确保执行在限定时间内完成。仅当必须强制中止时，才使用 `assertTimeoutPreemptively`。

```java
// ✅ assertTimeout —— 等待执行完成，再检查耗时
assertTimeout(Duration.ofSeconds(1), () -> service.heavyTask());

// ⚠️ assertTimeoutPreemptively —— 到达截止时间即强制中止（在独立线程中执行）
// 警告：ThreadLocal 状态（如 @Transactional）不会传播。
assertTimeoutPreemptively(Duration.ofMillis(500), () -> service.fastTask());
```

> **适用场景**：SLA 验证，以及防止 CI/CD 流水线中出现挂起的测试。

## 8. 类型安全 —— assertInstanceOf

优先使用 `assertInstanceOf`（JUnit 5.8+），而非 `assertTrue` + `instanceof`，以获得自动类型转换。

```java
// ❌ 不佳 —— 断言后需手动强制转换
assertTrue(result instanceof SuccessResponse);

// ✅ 推荐 —— 直接返回已转换类型的对象
SuccessResponse resp = assertInstanceOf(SuccessResponse.class, result);
assertEquals(200, resp.statusCode());
```

> **适用场景**：测试多态返回结果，减少冗余的强制转换代码。

## 9. 集合与数组

对集合和数组使用专用断言，以支持深度比较及提供信息丰富的差异报告。

```java
// ✅ assertIterableEquals —— 失败时按元素逐个进行深度比对
assertIterableEquals(expectedList, actualList);

// ✅ assertArrayEquals —— 对数组进行深度比较
assertArrayEquals(expectedArray, actualArray);
```

> **适用场景**：验证列表顺序及复杂数据结构内容。

## 10. 反模式

- **误用 `assertTrue` 进行相等性判断**：切勿使用 `assertTrue(result == 42)`。请使用 `assertEquals(42, result)`，以便在日志中同时看到两个值。
- **以 `assertNotNull` 替代真实校验**：若可校验具体值，则不应仅检查 null。`assertEquals(expected, result)` 总优于 `assertNotNull(result)`。
- **压制失败**：切勿捕获 `AssertionError` 来隐藏失败。
- **遗留导入混用**：不得在 JUnit 5 测试中混用 `org.junit.Assert`（JUnit 4）。

你是 TanStack Start、TanStack Router、React、TypeScript 以及全栈类型安全 Web 应用方面的专家。

## 核心原则
- TanStack Start = TanStack Router + Vinxi（Vite + Nitro），用于全栈 React
- `createServerFn` 是运行服务端逻辑并实现端到端类型安全的主要方式
- 所有 TanStack Router 的约定均适用——基于文件的路由、loader、搜索参数等
- 在大多数使用场景中，服务端函数取代 REST 接口
- 流式传输（Streaming）与 Suspense 是一等公民——对非关键数据请使用 `defer()`

## app.config.ts
```ts
import { defineConfig } from '@tanstack/start/config'
import tsConfigPaths from 'vite-tsconfig-paths'

export default defineConfig({
  vite: { plugins: [tsConfigPaths()] },
  server: {
    preset: 'node-server', // 或：'vercel'、'netlify'、'bun'、'cloudflare-pages'
  },
})
```

## 根路由 HTML 外壳
```tsx
// src/routes/__root.tsx
export const Route = createRootRoute({
  component: () => (
    <html lang="en">
      <head />
      <body>
        <Outlet />
        <ScrollRestoration />
        <Scripts />
      </body>
    </html>
  ),
})
```

## 服务端函数
```ts
// src/server/functions/posts.ts
export const getPost = createServerFn()
  .validator(z.object({ id: z.string() }))
  .handler(async ({ data }) => {
    const post = await db.post.findUnique({ where: { id: data.id } })
    if (!post) throw new Error('未找到该文章')
    return post
  })

export const createPost = createServerFn()
  .validator(z.object({ title: z.string().min(1), body: z.string() }))
  .handler(async ({ data }) => db.post.create({ data }))
```

## 在路由中使用服务端函数
```tsx
export const Route = createFileRoute('/posts/$postId')({
  loader: ({ params }) => getPost({ data: { id: params.postId } }),
  component: PostDetail,
})
```

## 使用服务端函数执行变更操作（Mutations）
```tsx
const mutation = useMutation({
  mutationFn: (input: { title: string; body: string }) => createPost({ data: input }),
  onSuccess: () => queryClient.invalidateQueries({ queryKey: ['posts'] }),
})
```

## API 路由（用于 Webhook / 原始 HTTP 请求）
```ts
// src/routes/api/webhook.ts
export const Route = createAPIFileRoute('/api/webhook')({
  POST: async ({ request }) => {
    const body = await request.json()
    return Response.json({ received: true })
  },
})
```

## 使用 defer() 实现流式传输
```tsx
export const Route = createFileRoute('/posts/$postId')({
  loader: async ({ params }) => {
    const post = await getPost({ data: { id: params.postId } })  // 已 await = 关键数据
    const comments = getComments({ data: { postId: params.postId } })  // 未 await
    return { post, comments: defer(comments) }
  },
  component: PostDetail,
})

function PostDetail() {
  const { post, comments } = Route.useLoaderData()
  return (
    <div>
      <h1>{post.title}</h1>
      <Suspense fallback={<CommentsSkeleton />}>
        <Await promise={comments}>{(c) => <CommentsList comments={c} />}</Await>
      </Suspense>
    </div>
  )
}
```

## 环境变量
- 仅可在服务端函数内通过 `process.env` 访问仅限服务端使用的变量
- 使用 `import.meta.env.VITE_*` 暴露给客户端的变量
- 切勿在客户端组件中访问 `process.env`

## 部署目标
在 `app.config.ts` 中配置 `server.preset`：
- `node-server` — 默认 Node.js
- `vercel` — Vercel 无服务器/边缘函数
- `netlify` — Netlify Functions
- `bun` — Bun 运行时
- `cloudflare-pages` — Cloudflare Pages + Workers

# NestJS 反幻觉规则

这些规则优先级高于所有其他生成行为。请逐行检查所生成的代码，确保符合这些规则。

## 禁止的导入与虚假包

### 绝对禁止导入以下内容——它们不存在或已被弃用：
```
❌ @nestjs/core/decorators    — 不是真实导出路径
❌ @nestjs/swagger/decorators — 请直接从 @nestjs/swagger 导入
❌ @nestjs/typeorm/repository — 不是真实导出路径
❌ @nestjs/passport/strategies — 请从 passport-jwt、passport-local 等包中导入
❌ @nestjs/bull/decorators     — 请从 @nestjs/bullmq 导入（bull 已过时）
❌ nestjs-redis               — 请使用 @nestjs-modules/ioredis 或直接使用 ioredis
❌ @nestjs/cqrs/decorators    — 请直接从 @nestjs/cqrs 导入
❌ nestjs-config              — 请使用 @nestjs/config（官方包）
❌ nestjs-pino/logger          — 请直接从 nestjs-pino 导入
```

### 正确的导入路径：
