# 示例集成测试

```js
import { test, expect } from '@playwright/test';

test.describe('注册表单集成测试', () => {
  test.beforeEach(async ({ page }) => {
    // 模拟 API 响应
    await page.route('**/api/register', async route => {
      const request = route.request();
      const body = await request.postDataJSON();

      if (body.email && body.email.includes('@')) {
        await route.fulfill({
          status: 200,
          body: JSON.stringify({ message: '注册成功' })
        });
      } else {
        await route.fulfill({
          status: 400,
          body: JSON.stringify({ error: '邮箱格式无效' })
        });
      }
    });

    // 导航至注册页面
    await page.goto('/register');
  });

  test('应提交表单并显示成功消息', async ({ page }) => {
    // 准备：使用有效数据填写表单
    await page.fill('[data-testid="name-input"]', 'John Doe');
    await page.fill('[data-testid="email-input"]', 'john@example.com');
    await page.fill('[data-testid="password-input"]', 'Password123');

    // 执行：提交表单
    await page.click('[data-testid="register-button"]');

    // 断言：验证成功消息是否可见
    await expect(page.locator('[data-testid="success-message"]')).toBeVisible();
    await expect(page.locator('[data-testid="success-message"]')).toContainText('注册成功');

    // 断言：验证是否跳转至仪表板页面
    await expect(page).toHaveURL(/.*\/dashboard/);
  });

  test('应在邮箱格式无效时显示错误消息', async ({ page }) => {
    // 准备：使用无效邮箱填写表单
    await page.fill('[data-testid="name-input"]', 'John Doe');
    await page.fill('[data-testid="email-input"]', 'invalid-email');
    await page.fill('[data-testid="password-input"]', 'Password123');

    // 执行：提交表单
    await page.click('[data-testid="register-button"]');

    // 断言：验证错误消息是否可见
    await expect(page.locator('[data-testid="error-message"]')).toBeVisible();
    await expect(page.locator('[data-testid="error-message"]')).toContainText('邮箱格式无效');

    // 断言：验证是否仍停留在注册页面
    await expect(page).toHaveURL(/.*\/register/);
  });

  test('应在提交前校验输入字段', async ({ page }) => {
    // 执行：不填写任何字段即提交表单
    await page.click('[data-testid="register-button"]');

    // 断言：表单校验错误应被显示
    await expect(page.locator('[data-testid="name-error"]')).toBeVisible();
    await expect(page.locator('[data-testid="email-error"]')).toBeVisible();
    await expect(page.locator('[data-testid="password-error"]')).toBeVisible();

    // 断言：不应发出网络请求
    // 可通过确认当前仍在注册页面来验证
    await expect(page).toHaveURL(/.*\/register/);
  });
});
```

# TypeScript 示例

```ts
import { test, expect } from '@playwright/test';

// 定义 API 响应的数据类型
interface ProductType {
  id: number;
  name: string;
  price: number;
  inStock: boolean;
}

interface CartSuccessResponse {
  message: string;
  cartCount: number;
}

interface CartErrorResponse {
  error: string;
}

test.describe('购物车集成测试', () => {
  test.beforeEach(async ({ page }) => {
    // 模拟商品 API
    await page.route('**/api/products', route => {
      route.fulfill({
        status: 200,
        body: JSON.stringify([
          { id: 1, name: 'Product A', price: 19.99, inStock: true },
          { id: 2, name: 'Product B', price: 29.99, inStock: true },
          { id: 3, name: 'Product C', price: 39.99, inStock: false }
        ] as ProductType[])
      });
    });

    // 模拟购物车 API
    await page.route('**/api/cart/add', async route => {
      const request = route.request();
      const body = await request.postDataJSON();

      if (body.productId === 3) {
        await route.fulfill({
          status: 400,
          body: JSON.stringify({
            error: '商品缺货'
          } as CartErrorResponse)
        });
      } else {
        await route.fulfill({
          status: 200,
          body: JSON.stringify({
            message: '商品已加入购物车',
            cartCount: 1
          } as CartSuccessResponse)
        });
      }
    });

    // 导航至商品页面
    await page.goto('/products');
  });

  test('应将有库存的商品加入购物车', async ({ page }) => {
    // 验证商品是否正常显示
    await expect(page.locator('[data-testid="product-item"]')).toHaveCount(3);

    // 将第一个商品加入购物车
    await page.locator('[data-testid="product-item"]').first()
      .locator('[data-testid="add-to-cart"]')
      .click();

    // 验证购物车数量已更新
    await expect(page.locator('[data-testid="cart-count"]')).toContainText('1');

    // 验证成功消息
    await expect(page.locator('[data-testid="cart-notification"]')).toBeVisible();
    await expect(page.locator('[data-testid="cart-notification"]')).toContainText('商品已加入购物车');
  });

  test('不应将缺货商品加入购物车', async ({ page }) => {
    // 尝试加入缺货商品（Product C）
    await page.locator('[data-testid="product-item"]').nth(2)
      .locator('[data-testid="add-to-cart"]')
      .click();

    // 验证错误消息
    await expect(page.locator('[data-testid="error-notification"]')).toBeVisible();
    await expect(page.locator('[data-testid="error-notification"]')).toContainText('商品缺货');

    // 验证购物车数量未更新
    await expect(page.locator('[data-testid="cart-count"]')).toContainText('0');
  });
});
```

