# 示例集成测试

```js
describe('注册表单集成测试', () => {
  beforeEach(() => {
    // 访问注册页面
    cy.visit('/register');

    // 模拟 API 响应
    cy.intercept('POST', '/api/register', (req) => {
      if (req.body.email && req.body.email.includes('@')) {
        req.reply({
          statusCode: 200,
          body: { message: '注册成功' }
        });
      } else {
        req.reply({
          statusCode: 400,
          body: { error: '邮箱格式无效' }
        });
      }
    }).as('registerRequest');
  });

  it('应提交表单并显示成功消息', () => {
    // 准备：使用有效数据填写表单
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="password-input"]').type('Password123');

    // 执行：提交表单
    cy.get('[data-testid="register-button"]').click();

    // 等待 API 请求完成
    cy.wait('@registerRequest').its('request.body').should('include', {
      name: 'John Doe',
      email: 'john@example.com'
    });

    // 断言：验证成功消息已显示
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', '注册成功');

    // 断言：验证已重定向至仪表板
    cy.url().should('include', '/dashboard');
  });

  it('应在邮箱格式无效时显示错误消息', () => {
    // 准备：使用无效邮箱填写表单
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('Password123');

    // 执行：提交表单
    cy.get('[data-testid="register-button"]').click();

    // 等待 API 请求完成
    cy.wait('@registerRequest');

    // 断言：验证错误消息已显示
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', '邮箱格式无效');

    // 断言：验证仍停留在注册页面
    cy.url().should('include', '/register');
  });

  it('应在提交前验证输入字段', () => {
    // 执行：不填写任何字段即提交表单
    cy.get('[data-testid="register-button"]').click();

    // 断言：表单验证错误应已显示
    cy.get('[data-testid="name-error"]').should('be.visible');
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('be.visible');

    // 断言：不应发出任何 API 请求
    cy.get('@registerRequest.all').should('have.length', 0);
  });
});
```

# TypeScript 示例

```ts
// 定义 API 响应类型
interface RegisterSuccessResponse {
  message: string;
}

interface RegisterErrorResponse {
  error: string;
}

describe('购物车集成测试', () => {
  beforeEach(() => {
    // 访问商品页面
    cy.visit('/products');

    // 模拟商品 API
    cy.intercept('GET', '/api/products', {
      statusCode: 200,
      body: [
        { id: 1, name: '商品 A', price: 19.99, inStock: true },
        { id: 2, name: '商品 B', price: 29.99, inStock: true },
        { id: 3, name: '商品 C', price: 39.99, inStock: false }
      ]
    }).as('getProducts');

    // 模拟购物车 API
    cy.intercept('POST', '/api/cart/add', (req) => {
      const productId = req.body.productId;
      if (productId === 3) {
        req.reply({
          statusCode: 400,
          body: { error: '商品缺货' }
        });
      } else {
        req.reply({
          statusCode: 200,
          body: {
            message: '商品已加入购物车',
            cartCount: 1
          }
        });
      }
    }).as('addToCart');
  });

  it('应将有库存的商品加入购物车', () => {
    // 等待商品加载完成
    cy.wait('@getProducts');

    // 验证商品已显示
    cy.get('[data-testid="product-item"]').should('have.length', 3);

    // 将第一个商品加入购物车
    cy.get('[data-testid="product-item"]').first()
      .find('[data-testid="add-to-cart"]')
      .click();

    // 等待 API 请求完成
    cy.wait('@addToCart').its('request.body').should('deep.equal', {
      productId: 1,
      quantity: 1
    });

    // 验证购物车数量已更新
    cy.get('[data-testid="cart-count"]').should('contain', '1');

    // 验证成功消息
    cy.get('[data-testid="cart-notification"]')
      .should('be.visible')
      .and('contain', '商品已加入购物车');
  });

  it('不应将缺货商品加入购物车', () => {
    // 等待商品加载完成
    cy.wait('@getProducts');

    // 尝试加入缺货商品（商品 C）
    cy.get('[data-testid="product-item"]').eq(2)
      .find('[data-testid="add-to-cart"]')
      .click();

    // 等待 API 请求完成
    cy.wait('@addToCart');

    // 验证错误消息
    cy.get('[data-testid="error-notification"]')
      .should('be.visible')
      .and('contain', '商品缺货');

    // 验证购物车数量未更新
    cy.get('[data-testid="cart-count"]').should('contain', '0');
  });
});
```

