# 示例端到端测试

为登录页面编写测试时，应采用以下模式：

```js
describe('登录页面', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.intercept('POST', '/api/login', (req) => {
      if (req.body.username === 'validUser' && req.body.password === 'validPass') {
        req.reply({ status: 200, body: { message: '登录成功' } });
      } else {
        req.reply({ status: 401, body: { error: '凭据无效' } });
      }
    }).as('loginRequest');
  });

  it('应允许用户使用有效凭据登录', () => {
    cy.get('[data-testid="username"]').type('validUser');
    cy.get('[data-testid="password"]').type('validPass');
    cy.get('[data-testid="submit"]').click();
    cy.wait('@loginRequest');
    cy.get('[data-testid="welcome-message"]').should('be.visible').and('contain', '欢迎，validUser');
  });

  it('应在凭据无效时显示错误消息', () => {
    cy.get('[data-testid="username"]').type('invalidUser');
    cy.get('[data-testid="password"]').type('wrongPass');
    cy.get('[data-testid="submit"]').click();
    cy.wait('@loginRequest');
    cy.get('[data-testid="error-message"]').should('be.visible').and('contain', '凭据无效');
  });
});
```

